1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	
4	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	  moonstone: 25,
11	};
12	
13	const BLOCK_SIZE = 3;
14	const BLOCK_PRICE: Record<string, number> = {
15	  rune: 60,
16	  moonstone: 60,
17	};
18	
19	const groupByType = (items: any[]): Record<string, any[]> => {
20	  const groups: Record<string, any[]> = {};
21	  for (const item of items) {
22	    (groups[item.type] ??= []).push(item);
23	  }
24	  return groups;
25	};
26	
27	const isPricedAsBlock = (type: string, count: number): boolean =>
28	  count === BLOCK_SIZE && type in BLOCK_PRICE;
29	
30	const priceGroup = (type: string, items: any[]): number =>
31	  isPricedAsBlock(type, items.length)
32	    ? BLOCK_PRICE[type]
33	    : items.length * BASE_PREMIUM_BY_TYPE[type];
34	
35	const CURSE_SURCHARGE_PERCENT = 50;
36	const HIGH_ENCHANTMENT_THRESHOLD = 5;
37	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
38	const LOYALTY_YEARS_THRESHOLD = 2;
39	const LOYALTY_DISCOUNT_PERCENT = 20;
40	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
41	
42	const applySurcharge = (amount: number, percent: number): number =>
43	  amount + (amount * percent) / 100;
44	
45	const applyDiscount = (amount: number, percent: number): number =>
46	  amount - (amount * percent) / 100;
47	
48	const quotePremium = (
49	  step: any,
50	  customer: any,
51	  isFollowUpContract: boolean
52	): number => {
53	  const groupsByType = groupByType(step.items);
54	  const basePremium = Object.entries(groupsByType).reduce(
55	    (sum, [type, items]) => sum + priceGroup(type, items),
56	    0
57	  );
58	  const itemSurcharge = step.items.reduce((sum: number, item: any) => {
59	    const itemBasePremium = BASE_PREMIUM_BY_TYPE[item.type];
60	    const surchargePercent =
61	      (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
62	      (item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
63	    return sum + (itemBasePremium * surchargePercent) / 100;
64	  }, 0);
65	  const isLoyalCustomer = customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
66	  const policyModifierPercent =
67	    FIRST_INSURANCE_SURCHARGE_PERCENT +
68	    (isLoyalCustomer ? -LOYALTY_DISCOUNT_PERCENT : 0) +
69	    (isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT : 0);
70	  const policyModifierAmount = (basePremium * policyModifierPercent) / 100;
71	  const premiumBeforeFee = basePremium + itemSurcharge + policyModifierAmount;
72	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
73	};
74	
75	export const runScenario = (scenario: any): { results: unknown[] } => {
76	  const results = scenario.steps.map((step: any, index: number) => {
77	    const isFollowUpContract = index > 0;
78	    return { premium: quotePremium(step, scenario.customer, isFollowUpContract) };
79	  });
80	  return { results };
81	};
